import pytest
from fastapi.testclient import TestClient
from qr.api import app
from qr.schemas import (
    QrModuleDrawer,
    QrFormat,
    QrErrorCorrection,
    QrColorMaskType,
    QrEyePosition,
)

client = TestClient(app)

SVG_DRAWERS = [
    QrModuleDrawer.SvgSquareDrawer,
    QrModuleDrawer.SvgCircleDrawer,
    QrModuleDrawer.SvgPathSquareDrawer,
    QrModuleDrawer.SvgPathCircleDrawer,
]

PIL_DRAWERS = [
    QrModuleDrawer.SquareModuleDrawer,
    QrModuleDrawer.GappedSquareModuleDrawer,
    QrModuleDrawer.CircleModuleDrawer,
    QrModuleDrawer.RoundedModuleDrawer,
    QrModuleDrawer.VerticalBarsDrawer,
    QrModuleDrawer.HorizontalBarsDrawer,
]


@pytest.mark.parametrize(
    "payload",
    [
        # Simple PNG test (will be assigned a default PIL drawer)
        {
            "data": "Hello World",
            "output": {"format": QrFormat.png.value, "as_json": False},
        },
        # Simple SVG test (will be assigned a default SVG drawer)
        {
            "data": "https://example.com",
            "output": {"format": QrFormat.svg.value, "as_json": False},
            "box_size": 8,
            "border": 2,
            "logo": None,
        },
    ],
)
def test_create_qr_valid_simple(payload, snapshot):
    # This logic ensures a default drawer is set and correctly formatted for the Union discriminator
    if payload["output"]["format"] == QrFormat.svg.value:
        # Use the value of the first SVG drawer
        drawer_type_value = SVG_DRAWERS[0].value
    else:
        # Use the value of the first PIL drawer
        drawer_type_value = PIL_DRAWERS[0].value

    # Overwrite/Set the module_drawer with the minimal required structure
    payload["module_drawer"] = {"type": drawer_type_value}

    response = client.post("/v1/qr", json=payload)
    assert response.status_code == 200
    assert response.content == snapshot


@pytest.mark.parametrize(
    "payload",
    [
        # 1. PNG + Rounded Drawer + Ratio
        {
            "data": "PNG Rounded Modules",
            "output": {"format": QrFormat.png.value},
            "module_drawer": {
                "type": QrModuleDrawer.RoundedModuleDrawer.value,
                "ratio": 0.6,
            },
            "box_size": 15,
        },
        # 2. SVG + Circle Path + Custom SVG Style/Background (returned as JSON)
        {
            "data": "SVG Path Circle with Custom Style",
            "output": {"format": QrFormat.svg.value, "as_json": True},
            "module_drawer": {
                "type": QrModuleDrawer.SvgPathCircleDrawer.value,
                "ratio": 0.9,
                "style": {
                    "svg": {"scale": 10},
                    "background": {
                        "fill": "none",
                        "stroke": "blue",
                        "stroke-width": 5,
                    },
                },
            },
            "fill_color": {"r": 100, "g": 0, "b": 100, "a": 255},
        },
        # 3. PNG + Logo + Error Correction H + Radial Gradient Mask
        {
            "data": "Logo Test with Gradient and High EC",
            "error_correction": QrErrorCorrection.H.value,
            "logo": {
                "image": ""
            },
            "output": {"format": QrFormat.png.value, "as_json": True},
            "color_mask": {
                "type": QrColorMaskType.RadialGradient.value,
                "options": {
                    "back_color": {"r": 255, "g": 255, "b": 255, "a": 255},
                    "center_color": {"r": 255, "g": 0, "b": 0, "a": 255},
                    "edge_color": {"r": 0, "g": 0, "b": 255, "a": 255},
                },
            },
            "module_drawer": {"type": QrModuleDrawer.SquareModuleDrawer.value},
        },
        # 4. PNG + Custom Eyes + Circle Module Drawer
        {
            "data": "Custom Eyes with Circle Modules",
            "output": {"format": QrFormat.png.value},
            "fill_color": {"r": 0, "g": 100, "b": 0, "a": 255},
            "back_color": {"r": 255, "g": 200, "b": 200, "a": 255},
            "eye_drawer": {
                QrEyePosition.top_left.value: {
                    "outer": {
                        "radius": 0.5,
                        "outline": "red",
                        "corners": [True, False, True, False],
                    },
                    "inner": {
                        "radius": 0.8,
                        "outline": {"r": 0, "g": 0, "b": 255, "a": 255},
                    },
                }
            },
            "module_drawer": {
                "type": QrModuleDrawer.CircleModuleDrawer.value,
                "ratio": 0.7,
            },
        },
        # 5. WEBP output with Horizontal Bars
        {
            "data": "WEBP Horizontal Bars",
            "output": {"format": QrFormat.webp.value},
            "module_drawer": {
                "type": QrModuleDrawer.HorizontalBarsDrawer.value,
                "shrink": 0.85,
            },
        },
        # 6. PNG + Vertical Bars + custom shrink
        {
            "data": "Vertical Bars with shrink",
            "output": {"format": QrFormat.png.value},
            "module_drawer": {
                "type": QrModuleDrawer.VerticalBarsDrawer.value,
                "shrink": 0.6,  # shrink controls bar thickness
            },
        },
        # 7. PNG + Horizontal Bars + custom shrink
        {
            "data": "Horizontal Bars with shrink",
            "output": {"format": QrFormat.png.value},
            "module_drawer": {
                "type": QrModuleDrawer.HorizontalBarsDrawer.value,
                "shrink": 0.7,
            },
        },
        # 8. PNG + Gapped Square + custom ratio
        {
            "data": "Gapped Square with ratio",
            "output": {"format": QrFormat.png.value},
            "module_drawer": {
                "type": QrModuleDrawer.GappedSquareModuleDrawer.value,
                "ratio": 0.5,  # ratio controls module gap
            },
        },
        # 9. PNG + Circle Module + custom ratio
        {
            "data": "Circle Modules with ratio",
            "output": {"format": QrFormat.png.value},
            "module_drawer": {
                "type": QrModuleDrawer.CircleModuleDrawer.value,
                "ratio": 0.65,
            },
        },
        # 10. PNG + Rounded Module + custom ratio
        {
            "data": "Rounded Modules with ratio",
            "output": {"format": QrFormat.png.value},
            "module_drawer": {
                "type": QrModuleDrawer.RoundedModuleDrawer.value,
                "ratio": 0.8,
            },
        },
    ],
)
def test_create_qr_valid_complex(payload, snapshot):
    # These complex payloads explicitly define the module_drawer and other options
    response = client.post("/v1/qr", json=payload)
    assert response.status_code == 200
    assert response.content == snapshot


@pytest.mark.parametrize(
    "payload",
    [
        # 1. Invalid Drawer/Format Combo: PIL drawer used with SVG output (fails custom model_validator)
        {
            "data": "Invalid Drawer/Format Combo",
            "output": {"format": QrFormat.svg.value},
            "module_drawer": {"type": QrModuleDrawer.SquareModuleDrawer.value},
        },
        # 2. Invalid Logo/EC Combo: Logo provided but EC is M (fails custom model_validator)
        {
            "data": "Invalid Logo/EC Combo",
            "error_correction": QrErrorCorrection.M.value,
            "logo": {
                "image": ""
            },
            "module_drawer": {"type": PIL_DRAWERS[0].value},
        },
    ],
)
def test_create_qr_invalid_functional(payload):
    # These tests check specific functional/cross-field validation errors (Pydantic/FastAPI returns 422)
    response = client.post("/v1/qr", json=payload)
    assert response.status_code == 422


@pytest.mark.parametrize(
    "payload",
    [
        {"data": "Hello", "output": {"format": "jpg"}},  # invalid output format value
        {},  # empty body (missing required 'data')
    ],
)
def test_create_qr_invalid_schema(payload):
    # These tests check general schema validation errors (Pydantic/FastAPI returns 422)
    response = client.post("/v1/qr", json=payload)
    assert response.status_code == 422


def test_create_qr_get_method():
    response = client.get("/v1/qr")
    assert response.status_code == 405


def test_create_qr_empty_data(snapshot):
    payload = {"data": ""}
    # Explicitly providing a minimal module_drawer for robustness
    payload["module_drawer"] = {"type": PIL_DRAWERS[0].value}
    response = client.post("/v1/qr", json=payload)
    assert response.status_code == 200
    assert response.content
    assert response.content == snapshot


def test_create_qr_large_data(snapshot):
    payload = {"data": "x" * 2000}
    # Explicitly providing a minimal module_drawer for robustness
    payload["module_drawer"] = {"type": PIL_DRAWERS[0].value}
